// One audio engine for audition, live playback, and export. Reference speed follows its original BPM.
async function prepareEvents(only=null){let out=[],bpm=p.bpm,step=15/bpm,secs=total()*step;for(let t of tracks()){if(only&&t.id!==only)continue;if(!t.on||!t.vol)continue;if(t.kind==='notes'){if(!t.notes.length)continue;let sounds=await getSounds(t.inst);for(let n of t.notes){let len=Math.min(n.l,total()-n.s);if(n.s<0||len<=0)continue;out.push({at:n.s*step,dur:len*step,n:{...n,s:0,l:len,v:n.v*t.vol/100},sounds,bpm,fx:studioFXMerge(t.fx,n.fx)})}}else{let b=await getBuffer(t.key);for(let n of t.clips){let at=n.s*step,dur=Math.min(n.len,b.duration-n.trim,secs-at);if(dur>0)out.push({at,dur,buffer:b,trim:n.trim,rate:1,gain:t.vol/100,fx:studioFXMerge(t.fx,n.fx)})}}}let r=ref();if(!only&&r?.mix&&r.vol){let b=await getBuffer(r.key),rate=bpm/r.bpm,at=Math.max(0,r.offset),trim=Math.max(0,-r.offset)*rate,dur=Math.min((b.duration-trim)/rate,secs-at);if(dur>0)out.push({at,dur,buffer:b,trim,rate,gain:r.vol/100})}for(let e of out)if(studioFXActive(e.fx)){e.dryDur=e.dur;e.dur=Math.min(secs-e.at,e.dur+studioFXTail(e.fx,bpm))}return out.sort((a,b)=>a.at-b.at)}
function eventBuffer(e,ac){if(studioFXActive(e.fx)){if(!e.cached){let y=studioFXEvent(e);if(!y.length)return null;let b=ac.createBuffer(1,y.length,RATE);b.copyToChannel(y,0);e.cached=b}return e.cached}if(e.buffer)return e.buffer;if(!e.cached){let y=render([e.n],e.sounds,e.dur,e.bpm);if(!y.length)return null;let b=ac.createBuffer(1,y.length,RATE);b.copyToChannel(y,0);e.cached=b}return e.cached}
let playToken=0;
function seekCursor(s){closeContext();let wasPlaying=!!live,only=live?.only??null;stopLive();cursor=clamp(snapAt(s),0,total());syncTransport();paintTimeline();paintOverview();paintPiano();if(wasPlaying&&cursor<total())startLive(only)}
function stopLive(reset=false){playToken++;if(live){clearInterval(live.timer);try{live.bus.disconnect()}catch{}for(let s of live.nodes)try{s.stop()}catch{}live=null}if(reset)cursor=0;if(S('sPlay')){syncTransport();paintTimeline();paintOverview();paintPiano()}}
async function startLive(only=null){if(live){stopLive();return}stop();stopPreview();stopAudition();let token=++playToken;try{let ac=audio();await ac.resume();let events=await prepareEvents(only);if(token!==playToken)return;let dur=total()*stepSec();if(cursor>=total())cursor=only?prView*16:0;else if(only&&(cursor<prView*16||cursor>=prGeometry().last))cursor=prView*16;let from=cursor*stepSec(),start=ac.currentTime+.08,bus=ac.createGain();bus.gain.value=.8;bus.connect(ac.destination);let state={start,from,bus,only,nodes:new Set(),timer:null};live=state;let cycle=0,index=0;function tick(){if(live!==state)return;let now=ac.currentTime,elapsed=Math.max(from,now-start+from);if(elapsed>=dur&&!loop){cursor=total();stopLive();return}cursor=clamp((loop?((elapsed%dur)+dur)%dur:elapsed)/stepSec(),0,total());if(S('sFollow').checked&&(cursor<view*16||cursor>=(view+span())*16))setView(Math.floor(cursor/16));S('sClock').textContent=timeFmt(cursor*stepSec());paintTimeline();paintOverview();paintPiano();if(!events.length||(!loop&&cycle>0))return;while((loop||cycle===0)&&cycle*dur+events[index].at<elapsed+.18){let e=events[index],at=cycle*dur+e.at,end=at+e.dur;if(end>elapsed&&end>from){let cut=Math.max(0,elapsed-at,from-at),b=eventBuffer(e,ac);if(b&&e.dur>cut){let s=ac.createBufferSource();s.buffer=b;let effected=studioFXActive(e.fx),rate=effected?1:e.rate??1;s.playbackRate.value=rate;let g=ac.createGain();g.gain.value=effected?1:e.gain??1;s.connect(g).connect(bus);let offset=(effected?0:e.trim??0)+cut*rate;try{s.start(Math.max(now,start+at-from),offset,(e.dur-cut)*rate);state.nodes.add(s);s.onended=()=>{state.nodes.delete(s);g.disconnect()}}catch{g.disconnect()}}}index++;if(index>=events.length){index=0;cycle++;if(!loop)break}if(!loop&&cycle>0)break}}syncTransport();state.timer=setInterval(tick,35);tick()}catch(e){stopLive();status('Falha na reprodução: '+e.message)}}
