async function exportStudio(){let b=S('exportStudio');b.disabled=true;stopLive();try{status('Preparando o WAV…');let events=await prepareEvents(),frames=Math.round(total()*stepSec()*RATE);if(!events.length)throw Error('Não há notas ou áudios ativos no arranjo.');let out=new Float32Array(frames),i=0;for(let e of events){let start=Math.round(e.at*RATE);if(studioFXActive(e.fx)){let y=studioFXEvent(e);for(let j=0;j<Math.min(y.length,frames-start);j++)out[start+j]+=y[j]*.8}else if(e.buffer){let src=e.buffer,rate=e.rate??1,chs=Array.from({length:src.numberOfChannels},(_,i)=>src.getChannelData(i)),count=Math.min(frames-start,Math.round(e.dur*RATE));for(let j=0;j<count;j++){let pos=(e.trim+j/RATE*rate)*src.sampleRate,k=Math.floor(pos),f=pos-k;if(k>=src.length-1)break;let v=0;for(let ch of chs)v+=ch[k]+(ch[k+1]-ch[k])*f;out[start+j]+=v/chs.length*e.gain*.8}}else{let y=render([e.n],e.sounds,e.dur,e.bpm);for(let j=0;j<Math.min(y.length,frames-start);j++)out[start+j]+=y[j]*.8}if(++i%12===0){status('Renderizando WAV · '+Math.round(i/events.length*100)+'%');await new Promise(r=>setTimeout(r,0))}}let peak=0;for(let x of out)peak=Math.max(peak,Math.abs(x));if(peak>1)for(let i=0;i<out.length;i++)out[i]/=peak;saveBlob(wav(out),'Ponto Estúdio - '+p.bpm+' BPM - '+studio().bars+' compassos.wav','audio/wav');status('WAV exportado · '+timeFmt(total()*stepSec()))}catch(e){status(e.message)}finally{b.disabled=false}}
