S('sBpm').oninput=()=>{let v=+S('sBpm').value;if(v>=60&&v<=220)S('sDuration').textContent=timeFmt(studio().bars*240/v)};S('sBars').oninput=()=>{let v=+S('sBars').value;if(v>=1&&v<=128)S('sDuration').textContent=timeFmt(v*240/p.bpm)};S('sBpm').onchange=()=>editStudio(()=>{p.bpm=clamp(Math.round(+S('sBpm').value)||130,60,220);S('bpm').value=p.bpm});S('sBars').onchange=()=>{let n=clamp(Math.round(+S('sBars').value)||1,1,128);if(n<studio().bars&&tracks().some(t=>(t.kind==='notes'?t.notes:t.clips).some(x=>x.s+(t.kind==='notes'?x.l:x.len/stepSec())>n*16))&&!confirm('Reduzir o arranjo e cortar notas e clipes fora do limite?')){syncTransport();return}editStudio(()=>{studio().bars=n;for(let t of tracks()){if(t.kind==='notes')t.notes=t.notes.filter(x=>x.s<n*16).map(x=>({...x,l:Math.min(x.l,n*16-x.s)}));else t.clips=t.clips.filter(x=>x.s<n*16).map(x=>({...x,len:Math.min(x.len,(n*16-x.s)*stepSec())}))}selection.clear()})};S('sSnap').onchange=()=>{paintTimeline();paintPiano()};S('sZoom').onchange=renderStudio;S('sPage').oninput=()=>setView(+S('sPage').value);S('sGo').onchange=()=>setView(+S('sGo').value-1);bindClick('sPrev',()=>setView(view-span()));bindClick('sNext',()=>setView(view+span()));bindClick('sPlay',()=>startLive());bindClick('sStop',()=>stopLive(true));bindClick('sLoop',()=>{loop=!loop;syncTransport()});bindClick('exportStudio',exportStudio);
