function resetBrowserProject(){stopLive(true);p.studio=fresh();p.bpm=130;media={};decoded.clear();soundCache.clear();waveforms.clear();past=[];future=[];selection.clear();prSelection.clear();clipBoard=null;prBoard=null;activeTrack=null;prView=0;hist=[];p.notes=[];p.bars=2;sel=0;S('bpm').value=p.bpm;view=0;listSounds();refList();renderStudio();status('Novo projeto criado.')}
function validateStudio(s,m){if(!s||!bound(s.bars,1,128)||!Array.isArray(s.tracks)||s.tracks.length>128)return false;const goodKey=k=>typeof k==='string'&&(k.startsWith('bank:')?byId.has(+k.slice(5)):!!m[k]);return s.tracks.every(t=>t&&typeof t.id==='string'&&typeof t.label==='string'&&bound(t.vol,0,100)&&typeof t.on==='boolean'&&(t.kind==='notes'?(builtin.includes(t.inst)||t.inst===custom||m[t.inst]?.type==='sample')&&Array.isArray(t.notes)&&t.notes.every(n=>typeof n.id==='string'&&Number.isFinite(n.s)&&n.s>=0&&n.s<s.bars*16&&Number.isFinite(n.l)&&n.l>0&&n.s+n.l<=s.bars*16+.001&&bound(n.k,36,96)&&bound(n.v,1,100)):t.kind==='audio'&&goodKey(t.key)&&Array.isArray(t.clips)&&t.clips.every(n=>typeof n.id==='string'&&Number.isFinite(n.s)&&n.s>=0&&n.s<s.bars*16&&Number.isFinite(n.len)&&n.len>0&&Number.isFinite(n.trim)&&n.trim>=0)))&&(!s.ref||goodKey(s.ref.key)&&Number.isFinite(s.ref.offset)&&s.ref.bpm>=40&&s.ref.bpm<=300&&bound(s.ref.vol,0,100)&&typeof s.ref.mix==='boolean')}
