function loadBrowserData(q){if(!valid(q))throw Error('Projeto incompatível com esta versão.');let m=q.studioMedia??{};if(typeof m!=='object'||Object.values(m).some(x=>!x||typeof x.data!=='string'||typeof x.name!=='string'||!['sample','ref','clip'].includes(x.type)||!Number.isFinite(x.duration)||x.duration<.03||(x.type==='sample'&&(!bound(x.root,36,96)||!Number.isFinite(x.from)||!Number.isFinite(x.len)||x.from<0||x.len<.03))))throw Error('Banco de áudios inválido.');if(q.studio&&!validateStudio(q.studio,m))throw Error('Arranjo inválido.');if(!q.studio&&q.desk&&!deskValid(q.desk))throw Error('Arranjo antigo inválido.');stopLive(true);stop();stopPreview();p=q;p.studio=q.studio??migrate(q.desk);delete p.desk;delete p.studioMedia;media=m;decoded.clear();soundCache.clear();waveforms.clear();past=[];future=[];hist=[];selection.clear();prSelection.clear();clipBoard=null;prBoard=null;activeTrack=null;prView=0;view=0;sel=0;S('bpm').value=p.bpm;syncCut();listSounds();refList();renderStudio();for(let key of new Set([...tracks().filter(t=>t.kind==='audio').map(t=>t.key),...(ref()?[ref().key]:[])]))getBuffer(key).then(paintTimeline).catch(()=>{});}
S('file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;let q=JSON.parse(await f.text());if(!valid(q))throw Error('Projeto incompatível com esta versão.');await switchBrowserProject(async()=>{loadBrowserData(q);browserActive=null;status('Projeto aberto do arquivo.')})}catch(err){status(err.message||'Não foi possível abrir o projeto.')}finally{e.target.value=''}};
