function check(){S('keyPreview').textContent=fmt(pending);let c=defs.find(([id])=>id!==editing&&keys[id]===pending);S('keyMsg').textContent=c?'Já usado em: '+c[1]:'Esc cancela. Alguns atalhos do navegador podem ser reservados.';S('keyApply').disabled=!!c;return !c}
