S('keyCancel').onclick=()=>d.close();S('keyReset').onclick=()=>{pending=defaults[editing];check();S('keyPreview').focus()};S('keyApply').onclick=()=>{if(!check())return;keys[editing]=pending;let ok=write();d.close();renderKeys();if(ok)status('Atalho atualizado: '+labels[editing])};
function page(piano,dir){if(piano){prView=clamp(prView+dir*+S('prZoom').value,0,studio().bars-1);S('prStart').value=prView+1;paintPiano()}else setView(view+dir*span())}
const actions={play:p=>startLive(p?prTrack:null),all:p=>{if(p){prT()?.notes.forEach(n=>prSelection.add(n.id));paintPiano()}else{tracks().forEach(t=>(t.kind==='notes'?t.notes:t.clips).forEach(n=>selection.add(n.id)));selectionInfo();paintTimeline()}},copy:p=>p?prCopy():copySel(),paste:p=>p?prPaste():pasteSel(),dup:p=>p?prDup():duplicateSel(),undo:()=>undoS(),redo:()=>redoS(),del:p=>p?prDelete():deleteSel(),pitchDown:p=>studioTranspose(p,-1),pitchUp:p=>studioTranspose(p,1),home:()=>jumpBrowserCursor(0,true),end:()=>jumpBrowserCursor(total(),true),left:()=>jumpBrowserCursor(cursor-snap()),right:()=>jumpBrowserCursor(cursor+snap()),barLeft:()=>jumpBrowserCursor(cursor-16),barRight:()=>jumpBrowserCursor(cursor+16),prev:p=>page(p,-1),next:p=>page(p,1),loop:()=>{loop=!loop;syncTransport()},select:p=>S(p?'prSelect':'sSelect').click(),draw:p=>S(p?'prDraw':'sDraw').click(),save:()=>browserActive?saveBrowserNow():showBrowserProjects(true),saveAs:()=>showBrowserProjects(true),projects:()=>showBrowserProjects(false)};
