 for(let k of studioFXKeys()){let label=document.createElement('label');label.style.cssText='display:grid;grid-template-columns:1fr 46px;gap:4px;align-items:center';let t=document.createElement('span');t.textContent=desc[k].join(' · ');let v=document.createElement('strong');v.id='fxv_'+k;v.textContent='0%';v.style.textAlign='right';let r=document.createElement('input');r.id='fx_'+k;r.type='range';r.min=0;r.max=100;r.value=0;r.style.gridColumn='1 / -1';r.oninput=()=>v.textContent=r.value+'%';label.append(t,v,r);S('fxControls').append(label)}
