 let mainFX=document.createElement('button');mainFX.textContent='FX da seleção';mainFX.onclick=()=>{let ns=tracks().filter(t=>t.kind==='notes').flatMap(t=>t.notes).filter(n=>selection.has(n.id));if(ns.length)openStudioFX(ns,ns.length+' nota(s)');else status('Selecione notas para adicionar efeitos.')};S('sDelete').after(mainFX);
